public static Option<NonEmpty<T>> ToNonEmptyOrNone<T>(this IEnumerable<T> source)
{
    ArgumentNullException.ThrowIfNull(source);

    using var enumerator = source.GetEnumerator();
    if (!enumerator.MoveNext())
    {
        return Option<NonEmpty<T>>.None;
    }

    var first = enumerator.Current;
    var rest = new List<T>(SequenceExtensions.GetInitialCapacity(source));
    while (enumerator.MoveNext())
    {
        rest.Add(enumerator.Current);
    }

    return Option<NonEmpty<T>>.Some(new NonEmpty<T>(first, rest));
}

public static Option<T> ElementAtOrNone<T>(this IEnumerable<T> source, int index)
{
    ArgumentNullException.ThrowIfNull(source);

    if (source is T[] array)
    {
        return (uint)index < (uint)array.Length
            ? Option<T>.Some(array[index]!)
            : Option<T>.None;
    }

    if (source is IList<T> list)
    {
        return (uint)index < (uint)list.Count
            ? Option<T>.Some(list[index]!)
            : Option<T>.None;
    }

    if (source is IReadOnlyList<T> readOnlyList)
    {
        return (uint)index < (uint)readOnlyList.Count
            ? Option<T>.Some(readOnlyList[index]!)
            : Option<T>.None;
    }

    if (index < 0)
    {
        return Option<T>.None;
    }

    var current = 0;
    foreach (var item in source)
    {
        if (current == index)
        {
            return Option<T>.Some(item!);
        }

        current++;
    }

    return Option<T>.None;
}

