        Assert.Same(exception, Assert.Throws<InvalidOperationException>(() =>
            Option.Some(1).Select(selector)));
        Assert.Same(exception, Assert.Throws<InvalidOperationException>(() =>
            Option.Some(1).SelectMany(binder, static (left, right) => left + right)));
        Assert.Same(exception, Assert.Throws<InvalidOperationException>(() =>
