            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => cancelledTask));
        Assert.Same(
            cancellation,
            await Assert.ThrowsAnyAsync<OperationCanceledException>(async () => { _ = await cancelledValueTask; }));
