        Assert.Equal(scenario is 0 or 1 or 4 or 5 ? 0 : 1, run.Source.Reads);
        Assert.Equal(IsSequence(identity) || scenario is 0 or 1 or 4 or 5 ? 0 : 1, run.Calls());
    }

