public void MatchValidatesCallbacksAndExecutesOnlyTheActiveBranch()
    {
        var validCalls = 0;
        var invalidCalls = 0;
        var valid = Validation<int, string>.Valid(3);
        var invalid = Validation<int, string>.Invalid("bad");

        Assert.Equal(
            6,
            valid.Match(
                value =>
                {
                    validCalls++;
                    return value * 2;
                },
                errors =>
                {
                    invalidCalls++;
                    return errors.Count;
                }));
        Assert.Equal(
            1,
            invalid.Match(
                value =>
                {
                    validCalls++;
                    return value * 2;
